const clock_font_t clock_font_small = {
    "0123456789", font_small_alpha, 18, 5, 7, 1, 12, 0,
};

const clock_font_t clock_font_date = {
    "0123456789%-~\302\260 ABCDEFGHIJLMNOPRSTUVWY", font_date_alpha, 158, 15, 21, 1, 36, 0,
};

const clock_font_t clock_font_humidity = {
    "0123456789%-", font_humidity_alpha, 158, 15, 21, 1, 36, 0,
};

const clock_font_t clock_font_temperature = {
    "0123456789-\302\260C", font_temperature_alpha, 280, 20, 28, 1, 48, 0,
};

const clock_font_t clock_font_time = {
    "0123456789: ", font_time_alpha, 630, 30, 42, 1, 72, 24,
};

const clock_font_t clock_font_narrow_time = {
    "0123456789: ", font_narrow_time_alpha, 483, 23, 42, 2, 57, 18,
};

const uint8_t *clock_font_glyph(const clock_font_t *font, uint32_t character, unsigned phase)
{
    if (font == NULL || character == '\0' || phase >= font->phases) {
        return NULL;
    }
    const unsigned char *cursor = (const unsigned char *)font->characters;
    size_t glyph_index = 0;
    while (*cursor != '\0') {
        uint32_t font_character = *cursor++;
        if ((font_character & 0xE0) == 0xC0 && (*cursor & 0xC0) == 0x80) {
            font_character = ((font_character & 0x1F) << 6) | (*cursor++ & 0x3F);
        }
        if (font_character == character) {
            return font->alpha + (glyph_index * font->phases + phase) * font->stride;
        }
        ++glyph_index;
    }
    return NULL;
}
